PAGES.hr_admin = { title: 'HR Control Centre', mod: 'hr_admin', render() {
  const M = HRM(), T = HRT(), tab = pcTab('hadm', 'org'), ed = can('hr_admin', 'Edit') || can('hr_admin', 'Configure Settings');
  const tabs = pcTabs('hadm', [['org', 'Organisation masters'], ['sanction', 'Position sanction'], ['leave', 'Leave & attendance policy'], ['approvals', 'Approval matrices'], ['docs', 'Document checklists'], ['lists', 'Separation, discipline & rating'], ['imports', 'Excel imports'], ['access', 'Roles & security']], 'org');
  let body;
  if (tab === 'org') body = `<div class="grid2"><div>${table('hrDesigs', [{ h: 'Designation', k: d => d.name, t: 'text' }, { h: 'Category', k: d => d.cat, t: 'text' }, { h: 'Grade', k: d => d.grade, t: 'text' }, { h: 'Default dept', k: d => d.dept, t: 'text' }, { h: 'Employees', k: d => hrEmps().filter(e => hrActive(e) && e.desig === d.name).length, t: 'num' }], M.designations, { compact: true, title: 'Designations', limit: 60 })}</div><div>${table('hrGrades', [{ h: 'Grade', k: g => g.id, t: 'text' }, { h: 'Band', k: g => g.band, t: 'text' }, { h: 'Min / month', k: g => g.min, t: 'inr' }, { h: 'Max / month', k: g => g.max, t: 'inr' }], M.grades, { compact: true, title: 'Grades & bands' })}<p class="small"><b>Entities:</b> ${M.entities.map(e => `${e.id} – ${esc(e.name)}`).join(' · ')}<br><b>Regions:</b> ${M.regions.join(', ')}<br><b>Zones:</b> ${M.zones.join(', ')}<br><b>Departments:</b> ${M.departments.join(', ')}<br><b>Employment types:</b> ${M.empTypes.join(', ')}<br><b>Hierarchy:</b> Employee → Reporting manager / HOD → Principal → Zonal Director → Regional Director → HR / Finance → CEO / CFO.</p>${ed ? '<div class="btnrow"><button class="btn sm" data-act="hrDesigForm">Add designation</button><button class="btn sm" data-act="hrDeptForm">Add department</button></div>' : ''}</div></div>`;
  else if (tab === 'sanction') { const P = hrPositions().filter(p => hrInBid(p.bid)); body = `<div class="note">Sanctioned positions per branch and department. Changes are logged; PRFs beyond sanction need the additional / unbudgeted route.</div>` + table('hrSanc', [{ h: 'Branch', k: p => hrBr(p.bid), t: 'text' }, { h: 'Department', k: p => p.dept, t: 'text' }, { h: 'Sanctioned', k: p => ed ? `<input type="number" value="${p.sanctioned}" data-act="hrSancEdit" data-k="${p.bid}|${p.dept}" style="width:70px">` : p.sanctioned, t: 'html', x: p => p.sanctioned }, { h: 'Working', k: p => p.active, t: 'num' }, { h: 'Vacant', k: p => p.vacant, t: 'num' }], P, { compact: true, limit: 200 }) + (ed ? '<div class="btnrow"><button class="btn sm primary" data-act="hrSancSave">Save sanction changes</button></div>' : ''); }
  else if (tab === 'leave') body = `<div class="form-grid">${pcFld('Grace period (min)', `<input id="ap_grace" type="number" value="${M.attPolicy.grace}" ${ed ? '' : 'disabled'}>`)}${pcFld('Late marks per ½-day LOP', `<input id="ap_late" type="number" value="${M.attPolicy.lateMarksPerHalfDay}" ${ed ? '' : 'disabled'}>`)}${pcFld('Half-day hours', `<input id="ap_half" type="number" value="${M.attPolicy.halfDayHours}" ${ed ? '' : 'disabled'}>`)}${pcFld('Full-day hours', `<input id="ap_full" type="number" value="${M.attPolicy.fullDayHours}" ${ed ? '' : 'disabled'}>`)}${pcFld('Overtime after (hours)', `<input id="ap_ot" type="number" value="${M.attPolicy.otAfterHours}" ${ed ? '' : 'disabled'}>`)}${pcFld('Regularisation limit / month', `<input id="ap_reg" type="number" value="${M.attPolicy.regLimit}" ${ed ? '' : 'disabled'}>`)}${pcFld('Regularisation window (days)', `<input id="ap_regd" type="number" value="${M.attPolicy.regDays}" ${ed ? '' : 'disabled'}>`)}${pcFld('No punch, no salary', pcSel('ap_npns', ['On', 'Off'], M.attPolicy.noPunchNoSalary ? 'On' : 'Off'))}${pcFld('Weekly off', `<input id="ap_off" value="${M.weeklyOff.join(', ')}" ${ed ? '' : 'disabled'}>`)}${pcFld('Teacher-student ratio', `<input id="ap_ratio" type="number" value="${M.cfg.ratio}" ${ed ? '' : 'disabled'}>`)}${pcFld('Probation (months) · notice (days)', `<input id="ap_prob" type="number" value="${M.cfg.probationMonths}" style="width:80px" ${ed ? '' : 'disabled'}> <input id="ap_notice" type="number" value="${M.cfg.noticeDays}" style="width:80px" ${ed ? '' : 'disabled'}>`)}${pcFld('CPT hours / year', `<input id="ap_cpt" type="number" value="${M.cfg.cptHoursPerYear}" ${ed ? '' : 'disabled'}>`)}</div>${ed ? '<div class="btnrow"><button class="btn sm primary" data-act="hrPolicySave">Save policy</button></div>' : ''}` + table('hrLtAdm', [{ h: 'Code', k: t => t.id, t: 'text' }, { h: 'Leave type', k: t => t.name, t: 'text' }, { h: 'Days', k: t => t.days, t: 'num' }, { h: 'Carry-forward', k: t => t.cf ? 'Yes (max ' + t.cfMax + ')' : 'No', t: 'text' }, { h: 'Encash', k: t => t.encash ? 'Yes' : 'No', t: 'text' }, { h: 'Eligibility', k: t => t.eligible, t: 'text' }], M.leaveTypes, { compact: true, title: 'Leave types (edit in the leave screen rules tab)' });
  else if (tab === 'approvals') body = `<div class="note">Approval matrices by request type; PRF routes differ for branch, head office and replacement requests and skip the CEO below ${INR(M.prfCeoAbove)} annual cost unless unbudgeted. Roles can be added / removed without developer intervention.</div>` + table('hrAppr', [{ h: 'Request type', k: r => r[0], t: 'text' }, { h: 'Route', k: r => r[1].join(' → '), t: 'text', cls: 'wrap' }, { h: '', k: r => ed ? `<button class="btn sm" data-act="hrApprEdit" data-k="${r[0]}">Edit</button>` : '', t: 'html', noexp: true }], Object.entries(M.approvals), { compact: true });
  else if (tab === 'docs') body = Object.entries(M.docChecklist).map(([k, L]) => `<h4 class="blk">${k}</h4><p class="small">${L.map(esc).join(' · ')}</p>`).join('') + (ed ? '<p class="small muted">Checklists by employee category; branch / designation-specific additions can be configured per designation.</p>' : '');
  else if (tab === 'lists') body = `<p><b>Separation reasons:</b> ${M.sepReasons.join(', ')}</p><p><b>Disciplinary categories:</b> ${M.discCats.join(', ')}</p><p><b>Rating scale:</b> ${M.ratingScale.map(r => `${r.v} – ${r.l}`).join(' · ')}</p><p><b>Shifts:</b> ${M.shifts.map(s => `${s.name} ${s.in}–${s.out}`).join(' · ')}</p>`;
  else if (tab === 'imports') body = `<div class="note">Controlled Excel import / export for employee masters, opening leave balances, attendance punches, salary structures, historical appraisals and bank details. Every import is validated, previewed and logged; bank-detail imports are restricted to Payroll / Finance.</div><div class="ctrls"><button class="btn" data-act="hrImportTemplate">Download import template</button>${can('hr_admin', 'Upload') ? '<label class="fld"><span>Import employees / opening balances (Excel)</span><input type="file" accept=".xlsx,.xls,.csv" data-act="hrImportRun"></label>' : ''}</div>` + table('hrImpLog', [{ h: 'When', k: i => tsLabel(i.at), t: 'text' }, { h: 'By', k: i => i.by, t: 'text' }, { h: 'File', k: i => i.file, t: 'text', cls: 'small' }, { h: 'Sheet', k: i => i.sheet, t: 'text' }, { h: 'Rows', k: i => i.rows, t: 'num' }, { h: 'Imported', k: i => i.ok, t: 'num' }, { h: 'Rejected', k: i => i.bad, t: 'num' }], T.imports || [], { compact: true, empty: 'No imports yet.' });
  else body = `<div class="note">Roles: System Admin, HR Admin, Corporate HR, Branch HR, Recruitment Executive, Payroll Executive, Finance Admin, CFO, Principal / Branch Head, HOD / Reporting Manager, Employee, Internal Auditor, Management Viewer. Users see only their permitted branches, teams and fields; Payroll has independent permissions and a separate menu; salary, bank, statutory, disciplinary and medical data are restricted; nothing is permanently deleted.</div>` + table('hrRoles', [{ h: 'Role', k: r => r, t: 'text' }, { h: 'Users', k: r => users().filter(u => u.role === r && u.status === 'Active').length, t: 'num' }, { h: 'HR screens', k: r => MODULES.filter(([m]) => m.startsWith('hr_') && (((Store.get('roles') || {})[r] || { perms: {} }).perms[m] || []).includes('View')).length, t: 'num' }, { h: 'Payroll screens', k: r => MODULES.filter(([m]) => m.startsWith('py_') && (((Store.get('roles') || {})[r] || { perms: {} }).perms[m] || []).includes('View')).length, t: 'num' }, { h: 'Sensitive data', k: r => HR_SENSITIVE_ROLES.includes(r) ? 'Salary, bank, statutory, disciplinary' : 'Restricted', t: 'text', cls: 'small' }], ['System Admin', 'HR Admin', 'Corporate HR', 'Branch HR', 'Recruitment Executive', 'Payroll Executive', 'Finance Admin', 'CFO', 'Principal', 'HOD', 'Employee', 'Internal Auditor', 'Read-Only Management User'], { compact: true }) + '<p class="small muted">Permissions are managed in Admin → Roles & permissions. Audit trail: Admin → Audit log (module "HRMS" / "Payroll").</p>';
  return card('HR control centre', tabs + body, { sub: 'System Admin and HR Admin configure policies, forms, workflows and approval levels without developer intervention.' });
} };
Object.assign(HR_ACT, {
  hrSancEdit: t => { App.ui.hrSancDraft = Object.assign({}, App.ui.hrSancDraft || {}, { [t.dataset.k]: +t.value }); },
  hrSancSave: () => { const D = App.ui.hrSancDraft || {}; if (!Object.keys(D).length) return toast('No changes.'); askReason('Update sanctioned strength', Object.entries(D).map(([k, n]) => `${k.split('|')[0] || 'HO'} ${k.split('|')[1]}: ${n}`).join(', ').slice(0, 200), async r => { const M = Store.clone(HRM()); const old = JSON.stringify(Object.fromEntries(Object.keys(D).map(k => [k, M.sanction[k]]))); Object.assign(M.sanction, D); await Store.put('hr', M); App.ui.hrSancDraft = {}; audit('HRMS', 'Position sanction updated', { old, new: JSON.stringify(D), reason: r }); closeModal(); toast('Sanction updated.'); }); },
  hrPolicySave: () => askReason('Save attendance & HR policy', 'Changes apply to future attendance calculations and requests.', async r => { const M = Store.clone(HRM()); const old = JSON.stringify(M.attPolicy); Object.assign(M.attPolicy, { grace: +v('ap_grace') || 10, lateMarksPerHalfDay: +v('ap_late') || 3, halfDayHours: +v('ap_half') || 4, fullDayHours: +v('ap_full') || 7, otAfterHours: +v('ap_ot') || 9, regLimit: +v('ap_reg') || 3, regDays: +v('ap_regd') || 7, noPunchNoSalary: v('ap_npns') === 'On' }); M.weeklyOff = (v('ap_off') || 'Sun').split(',').map(x => x.trim()).filter(Boolean); M.cfg.ratio = +v('ap_ratio') || 25; M.cfg.probationMonths = +v('ap_prob') || 6; M.cfg.noticeDays = +v('ap_notice') || 30; M.cfg.cptHoursPerYear = +v('ap_cpt') || 30; await Store.put('hr', M); audit('HRMS', 'HR policy updated', { old, new: JSON.stringify(M.attPolicy), reason: r }); closeModal(); toast('Policy saved.'); }),
  hrApprEdit: t => { const k = t.dataset.k, route = HRM().approvals[k]; modal(`Approval route · ${k}`, `<label class="fld"><span>Roles in order (comma separated)</span><input id="ar_route" value="${esc(route.join(', '))}"></label><p class="small muted">Available: Reporting Manager, HOD, Principal, Zonal Director, Regional Director, HR, HR Admin, Finance, Payroll Executive, Finance Admin, CFO, CEO, Final Approver.</p>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="hrApprOk" data-k="${k}">Save</button>`); },
  hrApprOk: async t => { const M = Store.clone(HRM()); const old = M.approvals[t.dataset.k].join(' → '); M.approvals[t.dataset.k] = (v('ar_route') || '').split(',').map(x => x.trim()).filter(Boolean); await Store.put('hr', M); audit('HRMS', 'Approval matrix changed', { old, new: M.approvals[t.dataset.k].join(' → ') }); closeModal(); toast('Saved.'); },
  hrDesigForm: () => modal('Add designation', `<div class="form-grid">${pcFld('Name', '<input id="dg_name">')}${pcFld('Category', pcSel('dg_cat', HR_CATS, 'Teaching'))}${pcFld('Grade', pcSel('dg_grade', HRM().grades.map(g => g.id), 'G3'))}${pcFld('Default department', pcSel('dg_dept', HRM().departments, 'Academics'))}</div>`, '<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="hrDesigOk">Add</button>'),
  hrDesigOk: async () => { const name = (v('dg_name') || '').trim(); if (!name) return; const M = Store.clone(HRM()); if (M.designations.some(d => d.name === name)) return toast('Exists.', 'bad'); M.designations.push({ name, cat: v('dg_cat'), grade: v('dg_grade'), dept: v('dg_dept') }); await Store.put('hr', M); audit('HRMS', 'Designation added', { new: name }); closeModal(); toast('Added.'); },
  hrDeptForm: () => modal('Add department', pcFld('Name', '<input id="dp_name">'), '<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="hrDeptOk">Add</button>'),
  hrDeptOk: async () => { const name = (v('dp_name') || '').trim(); if (!name) return; const M = Store.clone(HRM()); if (!M.departments.includes(name)) M.departments.push(name); await Store.put('hr', M); audit('HRMS', 'Department added', { new: name }); closeModal(); toast('Added.'); },
  hrImportRun: t => { const f = t.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = async () => { try { const wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' }); const sheet = wb.SheetNames[0], raw = XLSX.utils.sheet_to_json(wb.Sheets[sheet], { defval: '', raw: false }); const norm = h => String(h).toLowerCase().replace(/[^a-z]/g, ''); const col = (o, ks) => { const k = Object.keys(o).find(h => ks.includes(norm(h))); return k ? o[k] : ''; }; const tx = Store.clone(HRT()); let ok = 0, bad = 0; if (/leave/i.test(sheet)) { raw.forEach(o => { const id = String(col(o, ['employeeid', 'empid'])).trim(); if (!hrEmp(id)) { bad++; return; } tx.balAdj[id] = tx.balAdj[id] || {}; ['CL', 'SL', 'EL'].forEach(k => { const val = col(o, [k.toLowerCase() + 'opening']); if (val !== '') { const cur = hrBalance(id, k); tx.balAdj[id][k] = (tx.balAdj[id][k] || 0) + (cur.alloc + cur.cf - cur.used - (+val || 0)); } }); ok++; }); } else { const nt = { employees: tx.newEmps, seq: tx.seq }; const mk = hrMkEmpFactory(nt, pcRng(Date.now() % 100000)); raw.forEach(o => { const name = String(col(o, ['name', 'employeename'])).trim(), desig = String(col(o, ['designation'])).trim(), bid = String(col(o, ['branchcode', 'branch'])).trim(); if (!name || !HRM().designations.some(d => d.name === desig) || (bid && !pcBranch(bid))) { bad++; return; } mk({ name, desig, bid, dept: String(col(o, ['department'])) || undefined, doj: rmParseDate(col(o, ['dateofjoining', 'doj'])) || PROC_TODAY, type: String(col(o, ['employmenttype'])) || 'Probation', gender: String(col(o, ['gender'])).toUpperCase().startsWith('M') ? 'M' : 'F', extra: { bio: String(col(o, ['biometricid'])), mobile: String(col(o, ['mobile'])), email: String(col(o, ['email'])), uan: String(col(o, ['uan'])), pan: String(col(o, ['pan'])), payrollEligible: false, docsVerified: false, userMade: true, importedFrom: f.name } }); ok++; }); } tx.imports = tx.imports || []; tx.imports.unshift({ at: nowIso(), by: App.user.name, file: f.name, sheet, rows: raw.length, ok, bad }); await hrSave(tx); audit('HRMS', 'Excel import', { new: `${f.name} · ${sheet} · ${ok} ok · ${bad} rejected` }); toast(`${ok} rows imported, ${bad} rejected.`); } catch (e) { toast('Import failed: ' + e.message, 'bad'); } }; rd.readAsArrayBuffer(f); t.value = ''; }
});
